deployment_address_mechanism_ck.value:
(
    "control"."deployment_address_reservation"."mechanism" in ('CREATE2','CREATE3') and "control"."deployment_address_reservation"."salt_namespace_digest" is not null and "control"."deployment_address_reservation"."salt_namespace_digest" ~ '^sha256:[0-9a-f]{64}$' and "control"."deployment_address_reservation"."effective_salt" is not null and "control"."deployment_address_reservation"."effective_salt" ~ '^0x[0-9a-f]{64}$'
  ) or ("control"."deployment_address_reservation"."mechanism" in ('TRANSACTION_CREATE','CREATE') and "control"."deployment_address_reservation"."salt_namespace_digest" is null and "control"."deployment_address_reservation"."effective_salt" is null and ("control"."deployment_address_reservation"."mechanism"<>'TRANSACTION_CREATE' or "control"."deployment_address_reservation"."sender_address"="control"."deployment_address_reservation"."creator_address"))

deployment_address_state_ck.value:
(
    "control"."deployment_address_reservation"."state"='RESERVED' and "control"."deployment_address_reservation"."handoff_at" is null and "control"."deployment_address_reservation"."expired_at" is null
  ) or ("control"."deployment_address_reservation"."state"='HANDOFF' and "control"."deployment_address_reservation"."handoff_at" is not null and "control"."deployment_address_reservation"."handoff_at">="control"."deployment_address_reservation"."created_at" and "control"."deployment_address_reservation"."handoff_at"<"control"."deployment_address_reservation"."expires_at" and "control"."deployment_address_reservation"."expired_at" is null
  ) or ("control"."deployment_address_reservation"."state"='EXPIRED' and "control"."deployment_address_reservation"."handoff_at" is null and "control"."deployment_address_reservation"."expired_at" is not null and "control"."deployment_address_reservation"."expired_at">="control"."deployment_address_reservation"."expires_at")
